cube('analytics_calendar_months', {
  sql: "SELECT * FROM cssql_oracle.analytics_calendar_alignment WHERE lane = 'months'", access_policy: [{ group: 'semantic_analyst', member_level: { includes: '*' }, row_level: { filters: [{ member: 'tenant', operator: 'equals', values: ['A'] }] } }],
  dimensions: { id: { sql: 'id', type: 'string', primary_key: true, public: true }, tenant: { sql: 'tenant', type: 'string' }, observed_at: { sql: 'observed_at', type: 'time' } }, measures: { amount: { sql: 'amount', type: 'sum' } }
});cube('analytics_calendar_leap', { sql: `WITH daily AS (
    SELECT tenant, CAST(observed_at AT TIME ZONE 'UTC' AS date) AS day, SUM(amount) AS value
    FROM cssql_oracle.analytics_calendar_alignment WHERE lane = 'leap' GROUP BY 1,2)
    SELECT c.tenant || ':' || CAST(c.day AS text) AS id, c.tenant, CAST(c.day AS timestamp) AS observed_at,
      CAST(m.prior_day AS text) AS prior_key, c.value AS current_value, p.value AS prior_value
    FROM daily c JOIN cssql_oracle.analytics_calendar_mapping m ON m.current_day = c.day AND m.calendar_key = 'leap' AND m.version = 1
    LEFT JOIN daily p ON p.tenant = c.tenant AND p.day = m.prior_day`, access_policy: [{ group: 'semantic_analyst', member_level: { includes: '*' }, row_level: { filters: [{ member: 'tenant', operator: 'equals', values: ['A'] }] } }],
    dimensions: { id: { sql: 'id', type: 'string', primary_key: true, public: true }, tenant: { sql: 'tenant', type: 'string' }, observed_at: { sql: 'observed_at', type: 'time' }, prior_key: { sql: 'prior_key', type: 'string' } },
    measures: { amount: { sql: 'current_value', type: 'sum' }, prior: { sql: 'prior_value', type: 'sum' } }
  });
