    (4,'B','months','2024-02-01T12:00:00Z',20000),
    (5,'A','leap','2023-02-28T12:00:00Z',20),(6,'A','leap','2024-02-29T12:00:00Z',40),(7,'B','leap','2023-02-28T12:00:00Z',9000),
    (8,'A','reporting','2024-01-01T12:00:00Z',10),(9,'A','reporting','2024-03-01T12:00:00Z',40),(10,'B','reporting','2024-01-01T12:00:00Z',9000),
    (11,'A','dst','2024-03-10T04:59:59Z',1),(12,'A','dst','2024-03-10T05:00:00Z',2),
    (13,'A','dst','2024-03-11T03:59:59Z',4),(14,'A','dst','2024-03-11T04:00:00Z',8),(15,'B','dst','2024-03-10T05:00:00Z',9000);
  CREATE TABLE cssql_oracle.analytics_calendar_mapping (calendar_key text NOT NULL, version integer NOT NULL, current_day date NOT NULL, prior_day date NOT NULL,
    PRIMARY KEY(calendar_key, version, current_day));
